#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t rows = 3, cols = 4;
    int *flat = malloc(rows * cols * sizeof(int));   /* 只分配一次 */
    if (!flat) return 1;

    int (*m)[4] = (int (*)[4])flat;                  /* 数组指针，直接二维下标 */

    for (size_t i = 0; i < rows; i++)
        for (size_t j = 0; j < cols; j++)
            m[i][j] = (int)(i * cols + j);

    for (size_t i = 0; i < rows; i++) {
        for (size_t j = 0; j < cols; j++) printf("%2d ", m[i][j]);
        printf("\n");
    }

    printf("一次 malloc + 一次 free，内存连续\n");
    free(flat);
    flat = NULL;
    return 0;
}
